        $amount=CompanyInvoiceAmounts::decimal(CompanyInvoiceAmounts::minor((string)$native['amount']));$unit=(new CompanyCurrencyUnits($this->db,$this->p))->resolveRead($native['currency']);$payload=['invoiceid'=>$invoice,'amount'=>$amount,'paymentmode'=>$native['paymentmode'],'paymentmethod'=>$native['paymentmethod'],'date'=>$native['date'],'transactionid'=>$native['transactionid'],'note'=>$native['note']];
