    }
    public function originalForStaffInOwned(int $issuer,int $actor,int $invoice,int $payment,string $request,int $observation):array{$this->boundary($issuer,$actor,false);return $this->originalInOwned($issuer,$invoice,$payment,$request,$observation);}
    private function decode(int $issuer,int $invoice,array $row):CompanyAsaasRefundData
