    public function capturedInOwned(int $issuer,int $actor,int $invoice,int $payment):?CompanyAsaasRefundData
    {
        $this->boundary($issuer,$actor,true);$rows=$this->rows('SELECT * FROM '.$this->p.'company_asaas_refund_postings WHERE payment_id=? FOR UPDATE',[$payment]);if(count($rows)>1)throw new DomainException('company_asaas_full_refund_proof_review');return $rows?$this->decode($issuer,$invoice,$rows[0]):null;
    }
    private function boundary(int $issuer,int $actor,bool $write):void{IssuerTransaction::assertOwned($this->db,$this->p,$this->tables());CompanyAsaasRefundSchema::ensure($this->db,$this->p,false);$acl=new IssuerResourceAccess($this->db,$this->p);if(!$acl->can($issuer,$actor,'invoices','view')||($write&&!$acl->can($issuer,$actor,'payments','delete')))throw new DomainException('company_asaas_full_refund_access_denied');}
    public function recordInOwned(int $issuer,int $actor,int $invoice,int $payment,CompanyAsaasRefundData $dto):bool
