        $this->boundary($issuer,$actor,true);$data=$dto->data();$original=$this->originalInOwned($issuer,$invoice,$payment,$data['refund_request_key'],$data['observation_id']);$validated=CompanyAsaasRefundData::fromCaptured($data,$original);$old=$this->capturedInOwned($issuer,$actor,$invoice,$payment);if($old){if(!hash_equals($old->fingerprint(),$validated->fingerprint()))throw new DomainException('company_asaas_full_refund_conflict');return false;}if($this->rows('SELECT request_key FROM '.$this->p.'company_asaas_refund_postings WHERE external_reference_key=? FOR UPDATE',[$dto->externalReferenceKey()]))throw new DomainException('company_asaas_full_refund_reference_reused');$key=self::key($issuer,$payment,$original['receipt_key']);$now=gmdate('Y-m-d H:i:s');$row=['request_key'=>$key,'issuer_id'=>$issuer,'invoice_id'=>$invoice,'payment_id'=>$payment,'origin_id'=>$original['origin_id'],'original_receipt_key'=>$original['receipt_key'],'external_reference_key'=>$dto->externalReferenceKey(),'currency'=>$original['currency'],'currency_basis'=>$original['currency_basis'],'amount'=>$dto->cashPrincipal(),'book_date'=>$data['book_date'],'payload_json'=>self::json($data),'payload_hash'=>$dto->fingerprint(),'created_by'=>$actor,'created_at'=>$now];$row['record_hash']=hash('sha256',self::json([$key,$issuer,$invoice,$payment,$original['origin_id'],$original['receipt_key'],$row['currency'],$row['currency_basis'],$row['payload_hash'],$actor,$now]));IssuerStorage::query($this->db,'INSERT INTO '.$this->p.'company_asaas_refund_postings (`'.implode('`,`',array_keys($row)).'`) VALUES('.implode(',',array_fill(0,count($row),'?')).')',array_values($row));$saved=$this->capturedInOwned($issuer,$actor,$invoice,$payment);if(!$saved||!hash_equals($saved->fingerprint(),$dto->fingerprint()))throw new RuntimeException('issuer_asaas_full_refund_unconfirmed');return true;
