    private function all(int $issuer,int $invoice):array{$out=[];foreach($this->rows('SELECT * FROM '.$this->p.'company_asaas_refund_postings WHERE invoice_id=? OR payment_id IN (SELECT id FROM '.$this->p.'invoicepaymentrecords WHERE invoiceid=?) ORDER BY payment_id FOR UPDATE',[$invoice,$invoice]) as $r){if((int)$r['issuer_id']!==$issuer||isset($out[(int)$r['payment_id']]))throw new DomainException('company_asaas_full_refund_proof_review');$out[(int)$r['payment_id']]=$this->decode($issuer,$invoice,$r)->data();}return $out;}
    public function forInvoiceInOwned(int $issuer,int $actor,int $invoice):array{if(!$this->tables())return [];$this->boundary($issuer,$actor,false);return $this->all($issuer,$invoice);}
    public function forPortalInOwned(CompanyPortalInvoices $portal,array $session,int $issuer,int $invoice):array{if(!$this->tables())return [];IssuerTransaction::assertOwned($this->db,$this->p,array_merge($this->tables(),$portal->balanceTables()));CompanyAsaasRefundSchema::ensure($this->db,$this->p,false);$identity=$portal->balanceIdentityInOwnedTransaction($session,$issuer,$invoice,$this->db,$this->p);$result=$this->all($issuer,$invoice);if($identity!==$portal->balanceIdentityInOwnedTransaction($session,$issuer,$invoice,$this->db,$this->p))throw new DomainException('company_portal_invoice_unavailable');return $result;}
